Mesh<Point, double> edges_mesh;
for (RT::Facet_const_iterator f = rt.facets_begin(); f != rt.facets_end(); ++f) {
    if (!is_large_facet(rt, *f, threshold)) {
        continue;
    }

    RT::Cell_handle c = f->first;
    unsigned k = f->second;

    // Get the three vertices of the facet
    std::vector<Point> facet_vertices;
    for (unsigned i = 0; i < 4; ++i) {
        if (i != k) {
            facet_vertices.push_back(c->vertex(i)->point());
        }
    }

    // Get the dual vertices (centers of the circumscribed spheres)
    std::vector<Point> dual_vertices;
    for (unsigned i = 0; i < 4; ++i) {
        if (i != k) {
            dual_vertices.push_back(c->vertex(i)->point());
        }
    }

    // Create edges between dual vertices
    for (unsigned i = 0; i < 3; ++i) {
        for (unsigned j = i + 1; j < 3; ++j) {
            // Calculate the edge segment between dual vertices
            Point p1 = dual_vertices[i];
            Point p2 = dual_vertices[j];

            // Calculate the area of the corresponding face
            Vector v1 = facet_vertices[i] - facet_vertices[0];
            Vector v2 = facet_vertices[j] - facet_vertices[0];
            double area = std::abs(CGAL::cross_product(v1, v2)).squared_length();

            // Add edge to mesh
            edges_mesh.push_back({static_cast<unsigned>(edges_mesh.vertices.size()),
                                 static_cast<unsigned>(edges_mesh.vertices.size() + 1)},
                                area);

            // Add vertices to mesh
            edges_mesh.vertices.push_back(p1);
            edges_mesh.vertices.push_back(p2);
        }
    }
}

return edges_mesh;

